CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('student','admin','employer')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS students(id SERIAL PRIMARY KEY,user_id INT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,student_id VARCHAR(40) UNIQUE NOT NULL,department VARCHAR(120) NOT NULL,program VARCHAR(120),year_of_study INT CHECK(year_of_study BETWEEN 1 AND 8),graduation_year INT,phone VARCHAR(40),resume_path TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS organizations(id SERIAL PRIMARY KEY,owner_user_id INT UNIQUE REFERENCES users(id) ON DELETE SET NULL,name VARCHAR(180) NOT NULL,email VARCHAR(255),phone VARCHAR(40),website TEXT,address TEXT,logo_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS opportunity_categories(id SERIAL PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities(id SERIAL PRIMARY KEY,organization_id INT NOT NULL REFERENCES organizations(id),title VARCHAR(220) NOT NULL,type VARCHAR(30) NOT NULL CHECK(type IN('Internship','Full-time','Part-time','Graduate Trainee','Contract')),category_id INT REFERENCES opportunity_categories(id),department VARCHAR(120),location VARCHAR(180),work_arrangement VARCHAR(20) NOT NULL DEFAULT 'On-site' CHECK(work_arrangement IN('Remote','On-site','Hybrid')),salary VARCHAR(120),duration VARCHAR(120),description TEXT NOT NULL,responsibilities TEXT,qualifications TEXT,skills TEXT,deadline DATE NOT NULL,vacancies INT NOT NULL DEFAULT 1 CHECK(vacancies>0),application_method VARCHAR(20) NOT NULL DEFAULT 'portal' CHECK(application_method IN('portal','external')),external_url TEXT,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','published','unpublished','expired')),featured BOOLEAN NOT NULL DEFAULT FALSE,created_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS applications(id SERIAL PRIMARY KEY,student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE,opportunity_id INT NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,cover_letter TEXT NOT NULL,resume_path TEXT,additional_documents TEXT[],status VARCHAR(30) NOT NULL DEFAULT 'Submitted' CHECK(status IN('Submitted','Under Review','Shortlisted','Interview Scheduled','Accepted','Rejected','Withdrawn')),review_notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(student_id,opportunity_id));
CREATE TABLE IF NOT EXISTS saved_opportunities(student_id INT REFERENCES students(id) ON DELETE CASCADE,opportunity_id INT REFERENCES opportunities(id) ON DELETE CASCADE,created_at TIMESTAMPTZ DEFAULT NOW(),PRIMARY KEY(student_id,opportunity_id));
CREATE TABLE IF NOT EXISTS announcements(id SERIAL PRIMARY KEY,title VARCHAR(220) NOT NULL,body TEXT NOT NULL,featured BOOLEAN DEFAULT FALSE,published BOOLEAN DEFAULT FALSE,created_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(220) NOT NULL,message TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contact_messages(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL,subject VARCHAR(220),message TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS interview_schedules(id SERIAL PRIMARY KEY,application_id INT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,scheduled_at TIMESTAMPTZ NOT NULL,location TEXT,meeting_url TEXT,notes TEXT,created_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activity_logs(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(220) NOT NULL,details JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_opportunities_status_deadline ON opportunities(status,deadline);
CREATE INDEX IF NOT EXISTS idx_opportunities_type ON opportunities(type);
CREATE INDEX IF NOT EXISTS idx_applications_student ON applications(student_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read_at);
